-------------------------------------------------------------------------------
-- n3_tb.vhd
--
-- Testbench for the 3-point DHT-IV: proposed and naive architectures.
--
-- Both implementations are simulated in parallel on the vectors from
-- vectors/n3_vectors.txt (generated by scripts/gen_vectors.py), applied at
-- one vector per clock cycle. Each output is compared with the expected
-- value; a summary with the maximum error is printed for each implementation.
--
-- The tolerances TOL_PROPOSED and TOL_NAIVE (in Q15.16 LSB) are the analytic
-- worst-case error bounds of each architecture: the sum of the maximum errors
-- of all roundings on the path to an output (1/2 LSB per rounded product,
-- 1 - 2^-k LSB per shift_right by k bits) plus 1/2 LSB for the rounding of
-- the expected value. The quantization error of the Q1.30 coefficients is
-- negligible (< 0.01 LSB).
-------------------------------------------------------------------------------
library ieee;
use ieee.std_logic_1164.all;
use std.textio.all;
use work.fixed_types_pkg.all;

entity n3_tb is
end entity n3_tb;

architecture sim of n3_tb is

    constant N            : positive := 3;
    constant VECTORS      : string   := "vectors/n3_vectors.txt";
    constant TOL_PROPOSED : natural  := 1;
    constant TOL_NAIVE    : natural  := 2;
    constant CLK_PERIOD   : time     := 10 ns;
    constant TIMEOUT      : time     := 1 ms;

    signal clk      : std_logic := '0';
    signal rst      : std_logic := '1';
    signal valid_in : std_logic;
    signal x_in     : sfix32_vector(0 to N - 1);

    signal valid_out_p, valid_out_n : std_logic;
    signal y_p, y_n                 : sfix32_vector(0 to N - 1);

    signal done_p, done_n     : boolean;
    signal errors_p, errors_n : natural;
    signal sim_done           : boolean := false;

begin

    ---------------------------------------------------------------------
    -- DUT: proposed architecture
    ---------------------------------------------------------------------
    dut_proposed : entity work.n3_prop_top
        port map (
            clk       => clk,
            rst       => rst,
            valid_in  => valid_in,
            x         => x_in,
            valid_out => valid_out_p,
            y         => y_p
        );

    ---------------------------------------------------------------------
    -- DUT: naive reference implementation
    ---------------------------------------------------------------------
    dut_naive : entity work.n3_naive
        port map (
            clk       => clk,
            rst       => rst,
            valid_in  => valid_in,
            x         => x_in,
            valid_out => valid_out_n,
            y         => y_n
        );

    ---------------------------------------------------------------------
    -- Stimulus and output checkers
    ---------------------------------------------------------------------
    stim : entity work.dht_tb_stim
        generic map (N => N, FILE_NAME => VECTORS)
        port map (clk => clk, rst => rst, x => x_in, valid => valid_in, done => open);

    check_proposed : entity work.dht_tb_check
        generic map (N => N, FILE_NAME => VECTORS, TAG => "proposed", TOL_LSB => TOL_PROPOSED)
        port map (clk => clk, valid => valid_out_p, y => y_p,
                  done => done_p, errors => errors_p);

    check_naive : entity work.dht_tb_check
        generic map (N => N, FILE_NAME => VECTORS, TAG => "naive   ", TOL_LSB => TOL_NAIVE)
        port map (clk => clk, valid => valid_out_n, y => y_n,
                  done => done_n, errors => errors_n);

    ---------------------------------------------------------------------
    -- Clock generation
    ---------------------------------------------------------------------
    clk_gen : process
    begin
        while not sim_done loop
            clk <= '0';
            wait for CLK_PERIOD / 2;
            clk <= '1';
            wait for CLK_PERIOD / 2;
        end loop;
        wait;
    end process;

    ---------------------------------------------------------------------
    -- Reset, end of simulation and timeout
    ---------------------------------------------------------------------
    control : process
        variable l : line;
    begin
        rst <= '1';
        wait for 3 * CLK_PERIOD;
        rst <= '0';

        wait until done_p and done_n for TIMEOUT;
        assert done_p and done_n
            report "Timeout: not all outputs were received" severity failure;

        if errors_p = 0 and errors_n = 0 then
            write(l, string'("=== All tests completed successfully ==="));
        else
            write(l, string'("=== Tests FAILED ==="));
        end if;
        writeline(output, l);

        sim_done <= true;
        wait;
    end process;

end architecture sim;
